import{_ as a,o as i,c as o,ae as r}from"./chunks/framework.RRduUuAx.js";const q=JSON.parse('{"title":"汇率切换说明","description":"","frontmatter":{},"headers":[],"relativePath":"v1/zh/guide/05-exchange-rate-guide.md","filePath":"v1/zh/guide/05-exchange-rate-guide.md"}'),t={name:"v1/zh/guide/05-exchange-rate-guide.md"};function e(n,l,s,h,u,g){return i(),o("div",null,[...l[0]||(l[0]=[r('<h1 id="汇率切换说明" tabindex="-1">汇率切换说明 <a class="header-anchor" href="#汇率切换说明" aria-label="Permalink to &quot;汇率切换说明&quot;">​</a></h1><h2 id="📋-概述" tabindex="-1">📋 概述 <a class="header-anchor" href="#📋-概述" aria-label="Permalink to &quot;📋 概述&quot;">​</a></h2><p>考拉记账支持多币种记账，并提供实时汇率查询和切换功能。本指南将帮助您了解如何切换汇率、设置本位币，以及汇率对账单显示的影响。</p><hr><h2 id="💰-什么是本位币" tabindex="-1">💰 什么是本位币？ <a class="header-anchor" href="#💰-什么是本位币" aria-label="Permalink to &quot;💰 什么是本位币？&quot;">​</a></h2><p><strong>本位币</strong>是您账本的主要货币，用于：</p><ul><li><strong>统一显示</strong>：所有账单金额都会换算成本位币显示</li><li><strong>统计计算</strong>：概览和统计页面的数据都基于本位币</li><li><strong>汇率基准</strong>：汇率列表以本位币为基准显示其他货币的汇率</li></ul><blockquote><p>💡 <strong>示例</strong>：</p><ul><li>如果您的本位币是 CNY（人民币），所有账单金额都会显示为人民币</li><li>即使您记录了一笔 100 USD 的账单，系统也会自动换算成人民币显示（如：720 CNY）</li></ul></blockquote><hr><h2 id="🚀-如何切换本位币" tabindex="-1">🚀 如何切换本位币 <a class="header-anchor" href="#🚀-如何切换本位币" aria-label="Permalink to &quot;🚀 如何切换本位币&quot;">​</a></h2><h3 id="方法一-在货币设置页面切换" tabindex="-1">方法一：在货币设置页面切换 <a class="header-anchor" href="#方法一-在货币设置页面切换" aria-label="Permalink to &quot;方法一：在货币设置页面切换&quot;">​</a></h3><ol><li>打开考拉记账 App</li><li>点击底部导航栏的 <strong>&quot;设置&quot;</strong> 图标</li><li>在设置页面中找到 <strong>&quot;货币设置&quot;</strong> 选项</li><li>点击进入货币设置页面</li><li>点击页面顶部的 <strong>&quot;本位币&quot;</strong> 选项</li><li>在弹出的货币选择器中选择新的本位币</li><li>确认选择后，系统会自动： <ul><li>更新账本的本位币设置</li><li>获取最新的汇率数据</li><li>刷新所有页面的金额显示</li></ul></li></ol><blockquote><p>⚠️ <strong>注意</strong>：</p><ul><li>切换本位币会影响所有账单的金额显示</li><li>系统会根据最新汇率自动换算</li><li>如果汇率数据不可用，可能会显示错误</li></ul></blockquote><h3 id="方法二-在账本详情页面切换" tabindex="-1">方法二：在账本详情页面切换 <a class="header-anchor" href="#方法二-在账本详情页面切换" aria-label="Permalink to &quot;方法二：在账本详情页面切换&quot;">​</a></h3><ol><li>打开考拉记账 App</li><li>进入 <strong>&quot;账本管理&quot;</strong> 页面</li><li>点击要修改的账本卡片右上角的 <strong>&quot;更多&quot;</strong> 按钮</li><li>进入账本详情页面</li><li>点击 <strong>&quot;账本货币&quot;</strong> 选项</li><li>在弹出的货币选择器中选择新的货币</li><li>确认选择后，系统会自动更新</li></ol><blockquote><p>📝 <strong>注意</strong>：</p><ul><li>账本货币就是本位币</li><li>修改账本货币等同于切换本位币</li><li>修改后会影响该账本的所有账单显示</li></ul></blockquote><hr><h2 id="📊-汇率列表说明" tabindex="-1">📊 汇率列表说明 <a class="header-anchor" href="#📊-汇率列表说明" aria-label="Permalink to &quot;📊 汇率列表说明&quot;">​</a></h2><h3 id="查看汇率列表" tabindex="-1">查看汇率列表 <a class="header-anchor" href="#查看汇率列表" aria-label="Permalink to &quot;查看汇率列表&quot;">​</a></h3><p>在货币设置页面，您可以：</p><ul><li><strong>查看所有货币</strong>：以分组形式显示所有支持的货币</li><li><strong>查看汇率</strong>：每个货币显示相对于本位币的汇率</li><li><strong>刷新汇率</strong>：点击右上角的刷新按钮，获取最新汇率</li></ul><h3 id="汇率分组" tabindex="-1">汇率分组 <a class="header-anchor" href="#汇率分组" aria-label="Permalink to &quot;汇率分组&quot;">​</a></h3><p>汇率列表按以下方式分组：</p><ul><li><strong>本位币</strong>：显示当前设置的本位币（汇率为 1.0）</li><li><strong>常用货币</strong>：显示常用货币（如：USD、EUR、GBP、JPY 等）</li><li><strong>按字母排序</strong>：其他货币按首字母分组显示</li></ul><h3 id="汇率更新" tabindex="-1">汇率更新 <a class="header-anchor" href="#汇率更新" aria-label="Permalink to &quot;汇率更新&quot;">​</a></h3><p>系统会在以下时机更新汇率：</p><ul><li><strong>切换本位币时</strong>：自动获取最新汇率</li><li><strong>手动刷新时</strong>：点击刷新按钮</li><li><strong>账本货币更新时</strong>：会自动获取最新汇率并刷新显示</li></ul><blockquote><p>💡 <strong>提示</strong>：</p><ul><li>汇率数据来自服务端，通过第三方汇率接口获取</li><li>如果网络不可用，会使用缓存的汇率数据</li><li>建议定期刷新，确保汇率准确</li></ul></blockquote><hr><h2 id="💱-汇率对账单的影响" tabindex="-1">💱 汇率对账单的影响 <a class="header-anchor" href="#💱-汇率对账单的影响" aria-label="Permalink to &quot;💱 汇率对账单的影响&quot;">​</a></h2><h3 id="金额显示" tabindex="-1">金额显示 <a class="header-anchor" href="#金额显示" aria-label="Permalink to &quot;金额显示&quot;">​</a></h3><p>当您记录一笔多币种账单时：</p><ol><li><strong>选择交易货币</strong>：在记录账单时，选择实际的交易货币（如：USD）</li><li><strong>输入金额</strong>：输入实际交易金额（如：100 USD）</li><li><strong>自动换算</strong>：系统会根据当前汇率自动换算成本位币显示（如：720 CNY）</li></ol><h3 id="统计计算" tabindex="-1">统计计算 <a class="header-anchor" href="#统计计算" aria-label="Permalink to &quot;统计计算&quot;">​</a></h3><p>所有统计和图表数据都基于本位币：</p><ul><li><strong>概览页面</strong>：显示本位币的总收支</li><li><strong>统计页面</strong>：图表数据基于本位币</li><li><strong>分类统计</strong>：各分类的金额都换算成本位币</li></ul><blockquote><p>📝 <strong>注意</strong>：</p><ul><li>如果汇率发生变化，历史账单的显示金额可能会变化</li><li>但原始交易金额不会改变</li><li>系统会使用<strong>当前汇率</strong>进行换算显示（因此刷新汇率后，历史账单的换算显示也可能随之变化）</li></ul></blockquote><hr><h2 id="🔄-汇率缓存机制" tabindex="-1">🔄 汇率缓存机制 <a class="header-anchor" href="#🔄-汇率缓存机制" aria-label="Permalink to &quot;🔄 汇率缓存机制&quot;">​</a></h2><h3 id="缓存说明" tabindex="-1">缓存说明 <a class="header-anchor" href="#缓存说明" aria-label="Permalink to &quot;缓存说明&quot;">​</a></h3><p>为了提高性能，系统会缓存汇率数据：</p><ul><li><strong>内存缓存</strong>：App 运行期间缓存在内存中</li><li><strong>数据库缓存</strong>：持久化存储在本地数据库</li><li><strong>缓存更新</strong>：当您手动刷新或切换本位币/账本货币时，会更新汇率并清理旧缓存</li></ul><h3 id="缓存清除" tabindex="-1">缓存清除 <a class="header-anchor" href="#缓存清除" aria-label="Permalink to &quot;缓存清除&quot;">​</a></h3><p>系统会在以下情况清除缓存：</p><ul><li><strong>切换本位币时</strong>：清除所有汇率缓存</li><li><strong>手动刷新时</strong>：清除旧缓存，获取新数据</li><li><strong>账本货币更新时</strong>：清除该账本的汇率缓存</li></ul><hr><h2 id="⚙️-汇率设置选项" tabindex="-1">⚙️ 汇率设置选项 <a class="header-anchor" href="#⚙️-汇率设置选项" aria-label="Permalink to &quot;⚙️ 汇率设置选项&quot;">​</a></h2><h3 id="手动修改汇率" tabindex="-1">手动修改汇率 <a class="header-anchor" href="#手动修改汇率" aria-label="Permalink to &quot;手动修改汇率&quot;">​</a></h3><p>在某些情况下，您可能需要手动修改汇率：</p><ol><li>在货币设置页面，找到要修改的货币</li><li>点击货币项，进入汇率设置页面</li><li>可以手动输入汇率值</li><li>保存后，该汇率会应用到所有相关计算</li></ol><blockquote><p>⚠️ <strong>注意</strong>：</p><ul><li>手动修改的汇率会覆盖自动获取的汇率</li><li>建议只在必要时手动修改</li><li>手动修改后，自动更新功能可能会覆盖您的修改</li></ul></blockquote><h3 id="汇率精度" tabindex="-1">汇率精度 <a class="header-anchor" href="#汇率精度" aria-label="Permalink to &quot;汇率精度&quot;">​</a></h3><p>系统支持以下汇率精度：</p><ul><li><strong>显示精度</strong>：汇率列表通常会显示多位小数</li><li><strong>计算精度</strong>：内部计算使用更高精度</li><li><strong>金额显示</strong>：最终金额通常保留 2 位小数</li></ul><hr><h2 id="🔧-常见问题" tabindex="-1">🔧 常见问题 <a class="header-anchor" href="#🔧-常见问题" aria-label="Permalink to &quot;🔧 常见问题&quot;">​</a></h2><h3 id="q1-切换本位币后-历史账单金额会变化吗" tabindex="-1">Q1：切换本位币后，历史账单金额会变化吗？ <a class="header-anchor" href="#q1-切换本位币后-历史账单金额会变化吗" aria-label="Permalink to &quot;Q1：切换本位币后，历史账单金额会变化吗？&quot;">​</a></h3><p><strong>A：</strong> 会的。切换本位币后：</p><ul><li>所有账单金额都会按照新本位币重新换算显示</li><li>但原始交易金额不会改变</li><li>系统会使用<strong>当前汇率</strong>进行换算显示（因此切换本位币或刷新汇率后，历史账单的换算显示也可能变化）</li></ul><h3 id="q2-汇率不准确怎么办" tabindex="-1">Q2：汇率不准确怎么办？ <a class="header-anchor" href="#q2-汇率不准确怎么办" aria-label="Permalink to &quot;Q2：汇率不准确怎么办？&quot;">​</a></h3><p><strong>A：</strong> 可以尝试：</p><ol><li>点击刷新按钮，获取最新汇率</li><li>检查网络连接是否正常</li><li>如果仍然不准确，可以手动修改汇率</li></ol><h3 id="q3-可以设置多个本位币吗" tabindex="-1">Q3：可以设置多个本位币吗？ <a class="header-anchor" href="#q3-可以设置多个本位币吗" aria-label="Permalink to &quot;Q3：可以设置多个本位币吗？&quot;">​</a></h3><p><strong>A：</strong> 不可以。每个账本只能有一个本位币。但您可以：</p><ul><li>创建多个账本，每个账本设置不同的本位币</li><li>在不同账本中记录不同货币的交易</li></ul><h3 id="q4-汇率多久更新一次" tabindex="-1">Q4：汇率多久更新一次？ <a class="header-anchor" href="#q4-汇率多久更新一次" aria-label="Permalink to &quot;Q4：汇率多久更新一次？&quot;">​</a></h3><p><strong>A：</strong></p><ul><li>汇率数据由服务端代理第三方接口获取，更新频率会随服务端策略与第三方数据源变化</li><li>App 会在切换本位币/账本货币或手动刷新时获取最新汇率</li><li>如果网络不可用，会使用缓存的汇率数据</li></ul><h3 id="q5-支持哪些货币" tabindex="-1">Q5：支持哪些货币？ <a class="header-anchor" href="#q5-支持哪些货币" aria-label="Permalink to &quot;Q5：支持哪些货币？&quot;">​</a></h3><p><strong>A：</strong> 考拉记账支持全球主要货币，包括：</p><ul><li>常用货币：CNY、USD、EUR、GBP、JPY、AUD、CAD 等</li><li>其他货币：支持 100+ 种货币</li></ul><h3 id="q6-汇率数据来源是什么" tabindex="-1">Q6：汇率数据来源是什么？ <a class="header-anchor" href="#q6-汇率数据来源是什么" aria-label="Permalink to &quot;Q6：汇率数据来源是什么？&quot;">​</a></h3><p><strong>A：</strong> 汇率数据来自第三方汇率 API，通过服务端代理获取，确保数据准确和稳定。</p><h3 id="q7-切换本位币会影响其他账本吗" tabindex="-1">Q7：切换本位币会影响其他账本吗？ <a class="header-anchor" href="#q7-切换本位币会影响其他账本吗" aria-label="Permalink to &quot;Q7：切换本位币会影响其他账本吗？&quot;">​</a></h3><p><strong>A：</strong> 不会。每个账本有独立的本位币设置，切换一个账本的本位币不会影响其他账本。</p><hr><h2 id="💡-使用技巧" tabindex="-1">💡 使用技巧 <a class="header-anchor" href="#💡-使用技巧" aria-label="Permalink to &quot;💡 使用技巧&quot;">​</a></h2><ol><li><strong>选择合适的本位币</strong>：根据主要交易货币选择本位币，减少换算误差</li><li><strong>定期刷新汇率</strong>：建议定期刷新汇率，确保数据准确</li><li><strong>多账本管理</strong>：如果经常处理多币种，可以创建多个账本，每个账本设置不同的本位币</li><li><strong>手动调整</strong>：如果自动汇率不准确，可以手动调整，但建议定期检查</li><li><strong>备份数据</strong>：重要账本建议定期备份，以防汇率数据丢失</li></ol><hr><p><strong>最后更新</strong>：2026年5月</p>',80)])])}const c=a(t,[["render",e]]);export{q as __pageData,c as default};
